import { NVector3, } from '../../../../lib';
import { GeometryUIBase } from '../GeometryUI/Base/GeometryUIBase';
// import { MouseEventData } from '../../AppCoreWrapper/IOWrapper/EventInteraction/MouseInteraction';
import { BlockImplementation } from '..';

import {
    ActiveCommandCommon,
    ActiveCommandSelection,
    ActiveCommandRect,
    ActiveCommandDrawingBlock
} from './ActiveCommandCommon';

export enum ACTIVECOMMAND_MODE {
    SELECT = 'SELECT', REMOVE = 'REMOVE',
    RECT = 'RECT',

    DRAWING_BLOCK = 'DRAWING_BLOCK',
}

export class ActiveCommandController {
    implementation: BlockImplementation;

    commands: any = {};
    activeCommand: ActiveCommandCommon | any;

    mouse: NVector3 = new NVector3(0, 0);
    capture: GeometryUIBase | undefined = undefined;
    private _ablePan: boolean = false;
    constructor(implementation: BlockImplementation) {
        this.implementation = implementation;

        this.commands = {
            // ........................................................................................................................ drawing annotation
            SELECT: new ActiveCommandSelection(this),

            RECT: new ActiveCommandRect(this),

            DRAWING_BLOCK: new ActiveCommandDrawingBlock(this),

        };

        this.SetActiveCommand(ACTIVECOMMAND_MODE.DRAWING_BLOCK);
    }
    public SetActiveCommand(theAC: ACTIVECOMMAND_MODE) {
        this.activeCommand = this.commands[theAC];
    }
    public get ablePan() {
        return this._ablePan;
    }
    public set ablePan(v: boolean) {
        this.implementation.implementations.nBlock.core.canvas.ablePan = v;
        this._ablePan = v;
    }
}